import{_ as a,o as t,c as r,a9 as o}from"./chunks/framework.asyjyako.js";const c=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":null}'),n={name:"guide/overview.md"};function i(s,e,l,p,h,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="Introduction" tabindex="-1">Introduction <a class="header-anchor" href="#Introduction" aria-label="Permalink to &quot;Introduction {#Introduction}&quot;">​</a></h1><p>A test can pass while the code it checks becomes slower. PerfChecker measures that change and helps you find where it comes from.</p><h2 id="The-problem" tabindex="-1">The problem <a class="header-anchor" href="#The-problem" aria-label="Permalink to &quot;The problem {#The-problem}&quot;">​</a></h2><ul><li><p>Unit tests check correctness, not cost.</p></li><li><p>A new temporary array, an extra parse or a different algorithm can slow an operation without failing any test.</p></li><li><p>Two runs on the same machine differ anyway, so a single number proves nothing.</p></li></ul><p>PerfChecker measures the same operation repeatedly, records the distribution, and keeps the conditions of the run with the numbers.</p><h2 id="The-workflow" tabindex="-1">The workflow <a class="header-anchor" href="#The-workflow" aria-label="Permalink to &quot;The workflow {#The-workflow}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choose a workload → measure it → save the result → compare or profile it</span></span></code></pre></div><ul><li><p><strong>Workload</strong> — one operation and its inputs, or an existing test item.</p></li><li><p><strong>Collector</strong> — what to record: time, allocations, a CPU profile, network counters.</p></li><li><p><strong>Run</strong> — the saved result, with source revision, runtime and settings attached.</p></li><li><p><strong>Comparison</strong> — the change from a reference, with optional pass/fail limits.</p></li></ul><p>Every interface reads the same saved run. Changing from the REPL to VS Code to the browser does not re-measure anything.</p><h2 id="What-runs,-and-where" tabindex="-1">What runs, and where <a class="header-anchor" href="#What-runs,-and-where" aria-label="Permalink to &quot;What runs, and where {#What-runs,-and-where}&quot;">​</a></h2><ul><li><p>The <strong>controller</strong> is your Julia process. It prepares versions, schedules work and writes reports.</p></li><li><p>A <strong>worker</strong> is a separate Julia process that loads and measures the target.</p></li><li><p>The collector decides the measurement boundary inside the worker.</p></li><li><p>Interface and plotting code never runs inside the worker.</p></li></ul><p>A whole-test measurement includes setup and assertions. An operation benchmark can exclude input preparation. Both are useful; pick the boundary that matches your question.</p><h2 id="Start" tabindex="-1">Start <a class="header-anchor" href="#Start" aria-label="Permalink to &quot;Start {#Start}&quot;">​</a></h2><ul><li><p><a href="./installation">Installation</a></p></li><li><p><a href="./first-check">Quickstart: measure a test</a></p></li><li><p><a href="./../tutorials/quick-tour">Measure an operation</a></p></li><li><p><a href="./understanding-measurements">Understand the result</a></p></li></ul><h2 id="Measure-safely" tabindex="-1">Measure safely <a class="header-anchor" href="#Measure-safely" aria-label="Permalink to &quot;Measure safely {#Measure-safely}&quot;">​</a></h2><ul><li><p>Keep a correctness check. A faster wrong answer is not an improvement.</p></li><li><p>Save the run. Reports record the source, environment and settings needed to judge comparability.</p></li><li><p>Do not promote a planned feature or platform to a real one. If a tool is unavailable, the report says <code>unavailable</code> — not zero.</p></li></ul><p><a id="Overview"></a><a id="Start-with-one-operation"></a><a id="Adapt-the-example"></a><a id="Save-a-result-and-reopen-it"></a><a id="Explore-a-larger-example"></a></p>',17)])])}const m=a(n,[["render",i]]);export{c as __pageData,m as default};
